ALTER TABLE session ADD CONSTRAINT session_user_fk FOREIGN KEY ("userId") REFERENCES "user" (id) ON DELETE CASCADE;
ALTER TABLE account ADD CONSTRAINT account_user_fk FOREIGN KEY ("userId") REFERENCES "user" (id) ON DELETE CASCADE;
ALTER TABLE workspace ADD CONSTRAINT workspace_owner_fk FOREIGN KEY (owner_id) REFERENCES "user" (id) ON DELETE CASCADE;
ALTER TABLE workspace_member ADD CONSTRAINT workspace_member_workspace_fk FOREIGN KEY (workspace_id) REFERENCES workspace (id) ON DELETE CASCADE;
ALTER TABLE workspace_member ADD CONSTRAINT workspace_member_user_fk FOREIGN KEY (user_id) REFERENCES "user" (id) ON DELETE CASCADE;
ALTER TABLE folder ADD CONSTRAINT folder_workspace_fk FOREIGN KEY (workspace_id) REFERENCES workspace (id) ON DELETE CASCADE;
ALTER TABLE folder ADD CONSTRAINT folder_parent_fk FOREIGN KEY (parent_id) REFERENCES folder (id) ON DELETE CASCADE;
ALTER TABLE file_entry ADD CONSTRAINT file_entry_workspace_fk FOREIGN KEY (workspace_id) REFERENCES workspace (id) ON DELETE CASCADE;
ALTER TABLE file_entry ADD CONSTRAINT file_entry_folder_fk FOREIGN KEY (folder_id) REFERENCES folder (id) ON DELETE SET NULL;
ALTER TABLE file_entry ADD CONSTRAINT file_entry_user_fk FOREIGN KEY (created_by) REFERENCES "user" (id) ON DELETE RESTRICT;
ALTER TABLE file_version ADD CONSTRAINT file_version_file_fk FOREIGN KEY (file_id) REFERENCES file_entry (id) ON DELETE CASCADE;
ALTER TABLE file_version ADD CONSTRAINT file_version_user_fk FOREIGN KEY (created_by) REFERENCES "user" (id) ON DELETE RESTRICT;
ALTER TABLE device_cursor ADD CONSTRAINT device_cursor_workspace_fk FOREIGN KEY (workspace_id) REFERENCES workspace (id) ON DELETE CASCADE;
ALTER TABLE device_cursor ADD CONSTRAINT device_cursor_user_fk FOREIGN KEY (user_id) REFERENCES "user" (id) ON DELETE CASCADE;
ALTER TABLE sync_event ADD CONSTRAINT sync_event_workspace_fk FOREIGN KEY (workspace_id) REFERENCES workspace (id) ON DELETE CASCADE;
ALTER TABLE sync_event ADD CONSTRAINT sync_event_file_fk FOREIGN KEY (file_id) REFERENCES file_entry (id) ON DELETE SET NULL;
ALTER TABLE sync_event ADD CONSTRAINT sync_event_user_fk FOREIGN KEY (created_by) REFERENCES "user" (id) ON DELETE RESTRICT;
CREATE INDEX IF NOT EXISTS workspace_member_user_idx ON workspace_member (user_id, created_at);
CREATE INDEX IF NOT EXISTS file_version_file_idx ON file_version (file_id, revision DESC);
CREATE INDEX IF NOT EXISTS sync_event_device_cursor_idx ON device_cursor (workspace_id, user_id, updated_at DESC);
